import assert from 'node:assert/strict';
import express from 'express';
import jwt from 'jsonwebtoken';
import service from '../../src/vercel.js';
import prisma,{atomic} from '../../src/db/prisma.js';
import {auditMiddleware} from '../../src/middlewares/auditMiddleware.js';
import {protect} from '../../src/middlewares/authMiddleware.js';
import {errorHandler} from '../../src/middlewares/errorMiddleware.js';
const app=express();app.use('/api/audit-test',express.json(),auditMiddleware,protect);app.post('/api/audit-test/fail',atomic(async()=>{await prisma.instructor.create({data:{name:'Must roll back',branches:'MIAMI',employeeId:'AUDIT-ROLLBACK'}});throw Error('Intentional test failure');}));app.use(service);app.use(errorHandler);
const server=app.listen(0,'127.0.0.1');await new Promise(r=>server.once('listening',r));const base=`http://127.0.0.1:${server.address().port}/api`;
async function req(path,method='GET',body,token){const r=await fetch(base+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body===undefined?undefined:JSON.stringify(body)});return {status:r.status,data:await r.json()};}
const ok=r=>{assert(r.status<300,JSON.stringify(r));return r.data;};
const login=async username=>ok(await req('/auth/login','POST',{username,password:'IsolatedDemoTest!123'})).token;
try{
 const admin=await login('main-admin'),mod=await login('Youssef Wael'),user=await login('Joe');
 const normal=await prisma.user.findUnique({where:{username:'Joe'}});
 const before=await prisma.systemLog.count();await req('/auth/me','GET',undefined,user);await req('/courses','GET',undefined,user);assert.equal(await prisma.systemLog.count(),before,'Browsing should not be logged');
 assert.equal((await req('/logs','GET',undefined,user)).status,403);
 assert.equal((await req('/courses','POST',{name:'Forbidden',code:'PRIVATE'},user)).status,403);
 let denied=await prisma.systemLog.findFirst({where:{actorUsername:'Joe',outcome:'FAILURE',category:'courses'},orderBy:{createdAt:'desc'}});assert(denied);assert.equal(denied.actorRole,'user');
 assert.equal((await req('/auth/login','POST',{username:'Joe',password:'NEVER_STORE_THIS_PASSWORD'})).status,401);
 assert.equal((await req('/auth/login','POST',{username:'unknown-login',password:'NEVER_STORE_THIS_PASSWORD'})).status,401);
 const failedLogins=await prisma.systemLog.findMany({where:{action:'LOGIN_LOCAL',outcome:'FAILURE'}});assert.equal(failedLogins.length,2);assert(!JSON.stringify(failedLogins).includes('NEVER_STORE_THIS_PASSWORD'));
 const visible=ok(await req('/logs','GET',undefined,mod));assert(visible.total>0);assert(visible.items.every(row=>row.actorRole==='user'));assert(!visible.items.some(row=>row.actorUsername==='Youssef Wael'));
 const adminEntry=await prisma.systemLog.findFirst({where:{actorUsername:'main-admin'},orderBy:{createdAt:'desc'}});assert.equal((await req('/logs/'+adminEntry.id,'GET',undefined,mod)).status,404);assert.equal((await req('/logs?actorUsername=main-admin','GET',undefined,mod)).data.total,0);
 const options=ok(await req('/logs/options','GET',undefined,mod));assert(!options.users.includes('main-admin'));assert(!options.users.includes('Unknown account'));
 const usersBefore=await prisma.user.findMany({orderBy:{id:'asc'}});
 const changed=ok(await req('/users/profile','PUT',{firstName:'Audit profile'},user));
 const profileLog=await prisma.systemLog.findFirst({where:{actorUsername:'Joe',action:'PROFILE_UPDATED'},orderBy:{createdAt:'desc'}});assert(profileLog);const profileDetails=ok(await req('/logs/'+profileLog.id,'GET',undefined,mod));assert(profileDetails.entries.some(e=>e.fields.some(f=>f.field==='firstName'&&f.after==='Audit profile')));
 await prisma.user.update({where:{id:normal.id},data:{role:'mod'}});assert.equal((await req('/logs/'+profileLog.id,'GET',undefined,mod)).status,200);assert.equal((await req('/logs/'+profileLog.id,'GET',undefined,user)).status,404);await prisma.user.update({where:{id:normal.id},data:{role:'user'}});
 assert.equal((await req('/audit-test/fail','POST',{password:'NEVER_STORE_THIS_PASSWORD'},user)).status,500);assert.equal(await prisma.instructor.count({where:{employeeId:'AUDIT-ROLLBACK'}}),0);const rolled=await prisma.systemLog.findFirst({where:{actorUsername:'Joe',outcome:'FAILURE',action:'CREATE'},orderBy:{createdAt:'desc'}});assert(rolled);assert.equal(rolled.details.committed,false);assert(rolled.details.changes.length>0);assert(!JSON.stringify(rolled).includes('NEVER_STORE_THIS_PASSWORD'));
 ok(await req('/auth/logout','POST',{},user));assert(await prisma.systemLog.findFirst({where:{actorUsername:'Joe',action:'LOGOUT'}}));
 const sso=jwt.sign({username:'audit-sso-user',role:'user',jti:'audit-sso-jti',email:'audit@example.invalid'},process.env.SSO_JWT_SECRET,{expiresIn:'30s'});ok(await req('/auth/sso','POST',{token:sso}));const ssoLog=await prisma.systemLog.findFirst({where:{actorUsername:'audit-sso-user',action:'LOGIN_SSO'}});assert.equal(ssoLog.authMethod,'SSO');assert(!JSON.stringify(ssoLog).includes(sso));
 await prisma.user.delete({where:{username:'audit-sso-user'}});assert(await prisma.systemLog.findUnique({where:{id:ssoLog.id}}));
 await assert.rejects(prisma.systemLog.update({where:{id:profileLog.id},data:{description:'Tampered'}}),/append-only/);await assert.rejects(prisma.systemLog.delete({where:{id:profileLog.id}}),/append-only/);
 assert.equal((await req('/logs/'+profileLog.id,'DELETE',{},admin)).status,404);
 const doomed=ok(await req('/courses','POST',{name:'Audit deletion example',code:'AUDIT-DELETE'},admin));
 const deletion=ok(await req('/courses/'+doomed.id+'/deletion-preview','GET',undefined,admin));
 ok(await req('/courses/'+doomed.id+'/permanent','DELETE',{confirm:true,confirmationName:deletion.name,version:deletion.version},admin));
 assert.equal(await prisma.course.findUnique({where:{id:doomed.id}}),null);
 const retained=await prisma.systemLog.findMany({where:{category:'courses',outcome:'SUCCESS'}});assert(retained.some(row=>JSON.stringify(row.details).includes(doomed.id)));
 assert.equal((await req('/activity-events','POST',{action:'IMPORT_FILE_REJECTED',message:'Invalid file type',fileName:'invalid.xls'},user)).status,200);assert(await prisma.systemLog.findFirst({where:{actorUsername:'Joe',action:'IMPORT_FILE_REJECTED',outcome:'FAILURE'}}));
 assert.equal((await req('/notifications/read-all','PUT',{},user)).status,200);
 assert.equal((await req('/branches/colors','POST',{name:'audit branch'},user)).status,403);
 assert.equal((await req('/branches/colors','POST',{name:'audit branch'},admin)).status,200);
 assert(await prisma.systemLog.findFirst({where:{category:'settings',outcome:'SUCCESS'}}));
 const malformed=await fetch(base+'/students',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+user},body:'{invalid-json'});assert.equal(malformed.status,400);await malformed.json();
 assert(await prisma.systemLog.findFirst({where:{actorUsername:'Joe',outcome:'FAILURE',category:'students'}}));
 const legacy=await prisma.systemLog.create({data:{actorUsername:'Joe',action:'COURSE_UPDATE',description:JSON.stringify({entity:'course',ids:['old-id'],changes:{name:{before:'Old course',after:'New course'}}})}});
 const historical=ok(await req('/logs/'+legacy.id,'GET',undefined,admin));assert.equal(historical.entries[0].fields[0].after,'New course');assert(!historical.description.startsWith('{'));assert.equal((await req('/logs/'+legacy.id,'GET',undefined,mod)).status,404);
 const all=ok(await req('/logs?outcome=FAILURE','GET',undefined,admin));assert(all.items.every(r=>r.outcome==='FAILURE'));assert(all.total>0);assert.equal((await req('/logs?from=2026-99-99','GET',undefined,admin)).status,400);
 assert.equal((await req('/exports/events','POST',{format:'pdf',status:'SUCCESS'},user)).status,403);ok(await req('/exports/events','POST',{format:'pdf',status:'FAILURE',month:'2026-10'},admin));assert(await prisma.systemLog.findFirst({where:{action:'REPORT_GENERATION_FAILED',outcome:'FAILURE'}}));
 console.log('PASS: immutable surviving logs, role snapshots and visibility on list/options/details, failed login/denied actions/rolled-back writes, password/SSO login and logout, secrets redacted, profile before/after, filters and report failures.');
}finally{server.closeAllConnections();await new Promise(r=>server.close(r));await prisma.$disconnect();}
